@startuml
class User {
  + UserID : int
  + Name : string
  + Email : string
  + DateOfBirth : date
}

class Account {
  + AccountNumber : int
}

class PersonalAccount {
}

class BusinessAccount {
  + CompanyName : string
  + MonthlyFee : double
}

class Page {
  + PageName : string
  + NumberOfVisits : int
}

class AdvertisementPage {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

User "1" -- "1" Account
Account --|> PersonalAccount
Account --|> BusinessAccount
Account "1" -- "*" Page
PersonalAccount "1" -- "*" Page : manage
PersonalAccount "1" -- "*" Page : privilege
BusinessAccount "1" -- "*" AdvertisementPage
AdvertisementPage --|> Page

@enduml

